        range: 1,
		pattern: "line",
        areaRange: 4
    });
    await api.executeDamageRoll(reactorToken, chosenTokens, 2, "energy", "TRANSMUTING SPARK", {ap: true});
	api.dispatchCustomTrigger("transmutingSpark", {triggeringToken: reactorToken})
}

async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (api.findEffectOnToken(reactorToken, "Transcending").name == "Transcending") {return;}
    const getFlag = api.getTokenFlags(reactorToken, 'transcendence')
    var dice = 0
    console.log(getFlag)
    if (getFlag == undefined) {
        var dice = 2
    } else  {var dice = getFlag - 1};
    if (dice != 1) {await api.addTokenFlags(reactorToken, {'transcendence': dice})};
    console.log(dice)
    if (dice == 1) {
        await api.addTokenFlags(reactorToken, {'transcendence': 3})
        await api.applyEffectsToTokens({
        tokens: [reactorToken],
        effectNames: {
            name: "Transcending",
            icon: "systems/lancer/assets/icons/white/orbital.svg",
            isCustom: true
        },
        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: reactorToken.id
        }
    });
}
}

